create table RB_BUS_ACCT_APPOINTMENT (PROD_NO VARCHAR(20) null  ,BASE_ACCT_NO VARCHAR(50) null  ,ISS_COUNTRY VARCHAR(3) null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,ORDER_NO VARCHAR(50) not null  ,APPOINTMENT_STATUS VARCHAR(2) null  ,DOCUMENT_ID VARCHAR(40) null  ,TRAN_DATE TIMESTAMP(3) null  ,CATEGORY_TYPE VARCHAR(3) null  ,RB_ACCT_TYPE VARCHAR(1) null  ,CLIENT_TYPE VARCHAR(3) null  ,TRAN_BRANCH VARCHAR(30) null  ,DOCUMENT_TYPE VARCHAR(6) null  ,CLIENT_NAME VARCHAR(100) null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,APPLY_DUE_DATE TIMESTAMP(3) null  , primary key(ORDER_NO));